  create temp table _e44 as
  select row_number() over () as eid,
         regexp_replace(lower(translate(cliente, 'áàäâãéèëêíìïîóòöôõúùüûñçÁÀÄÂÃÉÈËÊÍÌÏÎÓÒÖÔÕÚÙÜÛÑÇ', 'aaaaaeeeeiiiiooooouuuuncaaaaaeeeeiiiiooooouuuunc')), '[^a-z0-9]', '', 'g') as k,
         titulo, d
  from _x44;

  create temp table _t44 as
  select t.id,
         regexp_replace(lower(translate(coalesce(c.name, ''), 'áàäâãéèëêíìïîóòöôõúùüûñçÁÀÄÂÃÉÈËÊÍÌÏÎÓÒÖÔÕÚÙÜÛÑÇ', 'aaaaaeeeeiiiiooooouuuuncaaaaaeeeeiiiiooooouuuunc')), '[^a-z0-9]', '', 'g') as k,
         ((to_jsonb(t) ->> 'created_at')::timestamptz at time zone 'UTC')::date as d
  from public.trackings t
  join public.companies c on c.id = t.company_id
  where (to_jsonb(t) ->> 'tenant_id') = v_tenant
    and coalesce(trim(t.deal_name), '') = '';

  create temp table _m44 (id uuid primary key, eid bigint unique, titulo text);

  -- pair same company + same day first, then the day after / before (time zones)
  foreach off in array array[0, 1, -1] loop
    insert into _m44 (id, eid, titulo)
    select a.id, b.eid, b.titulo
    from (select t.id, t.k, t.d, row_number() over (partition by t.k, t.d order by t.id) rn
            from _t44 t where not exists (select 1 from _m44 m where m.id = t.id)) a
    join (select e.eid, e.k, e.d + off as d, e.titulo, row_number() over (partition by e.k, e.d order by e.titulo, e.eid) rn
            from _e44 e where not exists (select 1 from _m44 m where m.eid = e.eid)) b
      on b.k = a.k and b.d = a.d and b.rn = a.rn
    where a.k <> ''
    on conflict do nothing;
  end loop;

  if apply is distinct from 'yes' then
    raise notice 'Preview only. To fill the titles change ''no'' to ''yes'' on the line marked FILL THE TITLES.';
    return;
  end if;

  if to_regclass('public.deals_bk44_titles') is null then
    create table public.deals_bk44_titles (id uuid primary key, old_name text, new_name text, at timestamptz default now());
    alter table public.deals_bk44_titles enable row level security;
  end if;
  insert into public.deals_bk44_titles (id, old_name, new_name)
  select t.id, t.deal_name, m.titulo from public.trackings t join _m44 m on m.id = t.id
  on conflict (id) do nothing;

  update public.trackings t set deal_name = m.titulo
  from _m44 m where m.id = t.id and coalesce(trim(t.deal_name), '') = '';
end $$;

-- summary + 20 examples
select 'SUMMARY' as what,
       (select count(*) from _t44)::text || ' deals without title · ' ||
       (select count(*) from _m44)::text || ' matched with the Excel · ' ||
       ((select count(*) from _t44) - (select count(*) from _m44))::text || ' left without match' as detail,
       null::text as company, null::date as created, null::text as title
union all
(select 'example', null, c.name, ((to_jsonb(t) ->> 'created_at')::timestamptz at time zone 'UTC')::date, m.titulo
 from _m44 m join public.trackings t on t.id = m.id join public.companies c on c.id = t.company_id
 order by c.name limit 20);
